-- modify "copyright_claims" table
ALTER TABLE "copyright_claims" ADD COLUMN "claim_scope" character varying NOT NULL DEFAULT 'video', ADD COLUMN "claimant_phone" character varying NOT NULL DEFAULT '', ADD COLUMN "claimant_address" character varying NOT NULL DEFAULT '', ADD COLUMN "original_work_url" character varying NOT NULL DEFAULT '', ADD COLUMN "original_work_media_id" character varying NOT NULL DEFAULT '', ADD COLUMN "proof_urls" jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN "proof_media_ids" jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN "infringing_segments" jsonb NULL, ADD COLUMN "accuracy_declared" boolean NOT NULL DEFAULT false, ADD COLUMN "signature_name" character varying NOT NULL DEFAULT '', ADD COLUMN "signed_at" timestamptz NULL, ADD COLUMN "remedy" character varying NOT NULL DEFAULT 'none', ADD COLUMN "remedy_state" character varying NOT NULL DEFAULT 'none', ADD COLUMN "takedown_deadline_at" timestamptz NULL, ADD COLUMN "warning_id" uuid NULL;
-- create index "copyrightclaim_remedy_state_takedown_deadline_at" to table: "copyright_claims"
CREATE INDEX "copyrightclaim_remedy_state_takedown_deadline_at" ON "copyright_claims" ("remedy_state", "takedown_deadline_at");
-- modify "strikes" table
ALTER TABLE "strikes" ADD COLUMN "appeal_status" character varying NOT NULL DEFAULT 'none', ADD COLUMN "appeal_message" character varying NOT NULL DEFAULT '', ADD COLUMN "appealed_at" timestamptz NULL, ADD COLUMN "expiry_announced_at" timestamptz NULL;
-- create index "strike_appeal_status_appealed_at" to table: "strikes"
CREATE INDEX "strike_appeal_status_appealed_at" ON "strikes" ("appeal_status", "appealed_at");
-- create index "strike_expiry_announced_at_expires_at" to table: "strikes"
CREATE INDEX "strike_expiry_announced_at_expires_at" ON "strikes" ("expiry_announced_at", "expires_at");
-- create "copyright_policy_settings" table
CREATE TABLE "copyright_policy_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "takedown_deadline_hours" bigint NOT NULL DEFAULT 48, "strike_lifetime_days" bigint NOT NULL DEFAULT 90, "warning_lifetime_days" bigint NOT NULL DEFAULT 180, "strike_window_days" bigint NOT NULL DEFAULT 90, "restriction_threshold" bigint NOT NULL DEFAULT 3, "suspension_review_threshold" bigint NOT NULL DEFAULT 3, "restriction_days" bigint NOT NULL DEFAULT 30, "updated_by" character varying NOT NULL DEFAULT '', "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
